@php
    $values = isset($submission) ? $submission->payload : [];
    $farmId = isset($submission) ? $submission->farm_id : ($selectedFarmId ?? null);
    $cropStage = old('status', $values['status'] ?? 'growing');
    $cropOptions = ['Palay' => 'Palay (rice)', 'Corn' => 'Corn', 'Vegetables' => 'Vegetables', 'Coconut' => 'Coconut', 'Banana' => 'Banana', 'Mango' => 'Mango', 'Calamansi' => 'Calamansi', 'Cassava' => 'Cassava'];
    $livestockOptions = ['Native chicken' => 'Native chicken', 'Broiler chicken' => 'Broiler chicken', 'Duck' => 'Duck', 'Swine' => 'Swine', 'Goat' => 'Goat', 'Cattle' => 'Cattle', 'Carabao' => 'Carabao'];
    $fishSpeciesOptions = ['Tilapia' => 'Tilapia', 'Bangus' => 'Bangus', 'Carp' => 'Carp', 'Shrimp' => 'Shrimp', 'Crab' => 'Crab'];
    $selectedFarm = collect($farmer->farms ?? [])->first(fn ($farm) => (string) $farm->id === (string) $farmId);
    $farmProfileProducts = collect($selectedFarm?->categories ?? [])->map(fn ($product) => trim((string) $product))->filter()->unique(fn ($product) => strtolower($product))->values();
    $profileProductsFor = function ($products, array $keywords) {
        return $products->filter(function ($product) use ($keywords) {
            $value = strtolower((string) $product);
            return collect($keywords)->contains(fn ($keyword) => str_contains($value, $keyword));
        })->values();
    };
    $profileCropProducts = $profileProductsFor($farmProfileProducts, ['palay', 'rice', 'corn', 'vegetable', 'coconut', 'banana', 'mango', 'calamansi', 'cassava']);
    $profileLivestockProducts = $profileProductsFor($farmProfileProducts, ['chicken', 'broiler', 'duck', 'swine', 'pig', 'goat', 'cattle', 'carabao']);
    $profileFishProducts = $profileProductsFor($farmProfileProducts, ['tilapia', 'bangus', 'carp', 'shrimp', 'crab', 'fish']);
    $storedCrop = old('crop_type', $values['crop_type'] ?? '');
    $selectedCrop = collect($cropOptions)->keys()->first(fn ($choice) => strcasecmp($choice, (string) $storedCrop) === 0) ?? $profileCropProducts->first(fn ($choice) => strcasecmp($choice, (string) $storedCrop) === 0);
    $customCrop = $selectedCrop === null && $storedCrop !== '' ? $storedCrop : old('crop_type_other', '');
    $storedAnimal = old('animal_type', $values['animal_type'] ?? '');
    $selectedAnimal = collect($livestockOptions)->keys()->first(fn ($choice) => strcasecmp($choice, (string) $storedAnimal) === 0) ?? $profileLivestockProducts->first(fn ($choice) => strcasecmp($choice, (string) $storedAnimal) === 0);
    $customAnimal = $selectedAnimal === null && $storedAnimal !== '' ? $storedAnimal : old('animal_type_other', '');
    $storedSpecies = old('species', $values['species'] ?? '');
    $selectedSpecies = collect($fishSpeciesOptions)->keys()->first(fn ($choice) => strcasecmp($choice, (string) $storedSpecies) === 0) ?? $profileFishProducts->first(fn ($choice) => strcasecmp($choice, (string) $storedSpecies) === 0);
    $customSpecies = $selectedSpecies === null && $storedSpecies !== '' ? $storedSpecies : old('species_other', '');
@endphp
